// RC6 projection tests (node --test). No model calls, no browser.
//
// Loads REAL engine bundles (tests/fixtures/, generated by
// make_rc6_fixtures.py) and the FROZEN graph_core.mjs, plus the REAL
// applyEngineState function extracted from the built living-world HTML.
// Asserts the projection matches engine state: verified receipts,
// capacities, bottleneck, synergy combo, opportunities, and the
// accepted/exploratory/rejected/stopped markers.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import {
  projectGenieBundleToLivingGraph,
  computeConstraintResonance,
  computeCounterfactualIntelligence,
  discoverSynergisticCombos,
  generateDynamicOpportunities,
  addPath,
  getNode,
} from "../living_world/graph_core.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const FIX = join(HERE, "fixtures");
const load = (name) => JSON.parse(readFileSync(join(FIX, name), "utf-8"));

// Extract the REAL applyEngineState from the built UI (not a copy).
const builtHtml = readFileSync(join(HERE, "..", "genie_living_world.html"), "utf-8");
const fnSrc = builtHtml.match(/function applyEngineState\(sess,bundle\)\{[\s\S]*?\n\}/);
assert.ok(fnSrc, "applyEngineState not found in built UI");
const applyEngineState = new Function(
  "getNode", "computeConstraintResonance", "computeCounterfactualIntelligence",
  `${fnSrc[0]}; return applyEngineState;`,
)(getNode, computeConstraintResonance, computeCounterfactualIntelligence);

// Extract the REAL describeDiscovery from the built UI (not a copy).
const discSrc = builtHtml.match(/function describeDiscovery\(sess\)\{[\s\S]*?\n\}/);
assert.ok(discSrc, "describeDiscovery not found in built UI");
const describeDiscovery = new Function(
  "discoverSynergisticCombos", "computeCounterfactualIntelligence",
  `${discSrc[0]}; return describeDiscovery;`,
)(discoverSynergisticCombos, computeCounterfactualIntelligence);

function project(bundle) {
  const sess = projectGenieBundleToLivingGraph(bundle, {
    trustedReceiverKeys: [bundle.receiver_public_key],
  });
  applyEngineState(sess, bundle);
  return sess;
}

test("genuine bundle verifies; forged / swapped / stale bundles do not", () => {
  const base = load("bundle_baseline.json");
  const ok = projectGenieBundleToLivingGraph(base, {
    trustedReceiverKeys: [base.receiver_public_key],
  });
  assert.equal(ok.verificationStatus, "RECEIVER_VERIFIED");
  assert.equal(ok.receiverAttested, true);

  const forged = JSON.parse(JSON.stringify(base));
  forged.accepted.state.bakery.computed.throughput_loaves_per_day = 9999;
  const bad = projectGenieBundleToLivingGraph(forged, {
    trustedReceiverKeys: [base.receiver_public_key],
  });
  assert.equal(bad.verificationStatus, "UNVERIFIED_IMPORT");

  const swapped = projectGenieBundleToLivingGraph(base, {
    trustedReceiverKeys: ["AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"],
  });
  assert.equal(swapped.verificationStatus, "UNVERIFIED_IMPORT");

  const noKey = projectGenieBundleToLivingGraph(base, {});
  assert.equal(noKey.verificationStatus, "UNVERIFIED_IMPORT");
});

test("baseline projection matches engine state (174, oven bottleneck)", () => {
  const base = load("bundle_baseline.json");
  const sess = project(base);
  const res = sess.graph.constraint_resonance;
  assert.equal(sess.verificationStatus, "RECEIVER_VERIFIED");
  assert.equal(res.system_throughput, 174);
  assert.equal(res.baseline_throughput, 174);
  assert.equal(res.bottleneck_id, "oven");
  assert.equal(res.baseline_net_daily_usd, 643);
  assert.deepEqual(res.throughput_band, [162, 186]);
  assert.equal(getNode(sess, "oven").capacity, 174);
  assert.equal(getNode(sess, "staff").capacity, 240);
  assert.equal(getNode(sess, "ingredients").capacity, 280);
  // Engine assumption text replaces the demo's "24 loaves/batch".
  assert.match(getNode(sess, "oven").detail, /29 loaves\/batch/);
  assert.equal(sess.graph.baseline_metrics.net_daily_usd, 643);
});

test("accepted oven2 projects as the new baseline (240, staff bottleneck)", () => {
  const acc = load("bundle_accepted_oven2.json");
  const sess = project(acc);
  const res = sess.graph.constraint_resonance;
  assert.equal(res.system_throughput, 240);
  assert.equal(res.baseline_throughput, 240);
  assert.equal(res.bottleneck_id, "staff");
  assert.equal(getNode(sess, "oven").capacity, 348);
  assert.equal(acc.accepted.state.bakery.computed.throughput_loaves_per_day, 240);
});

test("pending exploratory projects as a tentative preview node", () => {
  const pend = load("bundle_pending_oven2.json");
  const sess = project(pend);
  const exp = sess.graph.nodes.find((n) => n.id.startsWith("exp_"));
  assert.ok(exp, "no exp_ node");
  assert.equal(exp.state, "tentative");
  assert.match(exp.detail, /Another oven/);
  // Accepted baseline is untouched by the pending proposal.
  assert.equal(sess.graph.constraint_resonance.baseline_throughput, 174);
});

test("rejected change projects as a rejected node; accepted preserved", () => {
  const rej = load("bundle_rejected.json");
  const sess = project(rej);
  const node = sess.graph.nodes.find((n) => n.id.startsWith("rej_"));
  assert.ok(node, "no rej_ node");
  assert.equal(node.state, "rejected");
  assert.equal(sess.graph.constraint_resonance.system_throughput, 174);
  assert.equal(
    rej.accepted.state_sha256,
    load("bundle_baseline.json").accepted.state_sha256,
  );
});

test("stopped bundle marks a node stopped", () => {
  const stopped = load("bundle_stopped.json");
  assert.equal(stopped.stopped, true);
  const sess = project(stopped);
  // The bakery graph has no 'exports' node, so the STOP marker lands on
  // the last node (scenario) — the projection's documented fallback.
  assert.equal(getNode(sess, "scenario").state, "stopped");
});

test("discovery-first: baseline surfaces the shift trap + oven/shift synergy", () => {
  const base = load("bundle_baseline.json");
  const sess = project(base);
  const d = describeDiscovery(sess);
  assert.ok(d, "no discovery on first run");
  assert.equal(d.comboId, "combo_oven2_hours");
  assert.equal(d.trapId, "hours");
  assert.equal(d.trapGain, 0);
  assert.equal(d.comboGain, 106);
  assert.equal(d.synergyBonus, 40);
  assert.equal(d.throughputBefore, 174);
  assert.equal(d.throughputAfter, 280);
  assert.equal(d.bottleneckBefore, "Oven");
  assert.equal(d.bottleneckAfter, "Ingredients");
  // Plain language: no optimization jargon in the visible copy.
  assert.match(d.title, /looks useless on its own/);
  assert.match(d.body, /changes nothing/);
  assert.match(d.body, /\+40/);
  assert.ok(!/counterfactual|synerg/i.test(d.title + d.body), "jargon leaked into copy");
});

test("discovery-first: after oven2 the next discovery recomputes (retarder trap)", () => {
  const acc = load("bundle_accepted_oven2.json");
  const sess = project(acc);
  const d = describeDiscovery(sess);
  assert.ok(d, "no discovery after oven2 accept");
  // Top combo by net gain: staggered shift + retarder rack (300/day).
  // The retarder alone is the trap (+0: staff clamps at 240; shop caps
  // the combo at 300, so the bonus is +20, not +60).
  assert.equal(d.comboId, "combo_hours_retarder_rack");
  assert.equal(d.trapId, "retarder_rack");
  assert.equal(d.trapGain, 0);
  assert.equal(d.synergyBonus, 20);
  assert.equal(d.throughputBefore, 240);
  assert.equal(d.throughputAfter, 300);
});

test("discovery-first: after oven2+hours no synergy remains, card hides", () => {
  const acc = load("bundle_accepted_oven2_hours.json");
  const sess = project(acc);
  // Every remaining pair has zero synergy bonus (add_baker+retarder
  // gains exactly its parts: +0 and +20). The card must hide rather
  // than invent a discovery; the next unlock is the single retarder.
  assert.equal(describeDiscovery(sess), null);
  const intel = sess.graph.counterfactual_intelligence;
  const singles = Object.fromEntries(
    intel.single_interventions.map((e) => [e.id, e.throughput_gain]),
  );
  assert.equal(singles.retarder_rack, 20);
  assert.equal(singles.add_baker, 0);
});

test("discovery-first: during an oven2 preview the card uses the preview baseline (F1)", () => {
  const base = load("bundle_baseline.json");
  const sess = project(base);
  // The live quick-move path: exploring oven2 adds branch_oven2, so the
  // preview state is 240 (Staff limit) while the accepted baseline stays 174.
  addPath(sess, "oven2");
  const res = sess.graph.constraint_resonance;
  assert.equal(res.system_throughput, 240);
  assert.equal(res.baseline_throughput, 174);
  const d = describeDiscovery(sess);
  assert.ok(d, "no discovery during oven2 preview");
  assert.equal(d.comboId, "combo_hours_retarder_rack");
  assert.equal(d.trapId, "retarder_rack");
  assert.equal(d.trapGain, 0);
  // ONE baseline per card, stated: the 240 preview baseline. Every number
  // on the card must be consistent with it — the F1 defect was a 174
  // start with preview-relative +60 / +$223 deltas and an accepted-baseline
  // clamp reason ("Oven caps output at 174").
  assert.equal(d.throughputBefore, 240);
  assert.equal(d.throughputAfter, 300);
  assert.equal(d.comboGain, 60);
  assert.equal(d.synergyBonus, 20);
  assert.equal(d.netGain, 223);
  assert.equal(d.bottleneckBefore, "Staff");
  assert.equal(d.bottleneckAfter, "Staff");
  assert.equal(d.nums, "From your 240 loaves/day preview: 240 → 300 loaves/day (+60) · Staff · +$223/day");
  assert.match(d.body, /Staff caps output at 240 loaves\/day/);
  assert.match(d.body, /\+20/);
  assert.ok(!/174/.test(d.nums + d.body), "accepted-baseline 174 leaked into preview card");
  assert.equal(d.isPreview, true);
  assert.match(d.fine, /240 loaves\/day preview baseline/);
  assert.ok(!/accepted project/.test(d.fine), "fine print still claims accepted baseline");
});

test("counterfactuals: oven+shift synergy +40, opportunities 2-4 with keep", () => {
  const base = load("bundle_baseline.json");
  const sess = project(base);
  const intel = sess.graph.counterfactual_intelligence;
  const singles = Object.fromEntries(
    intel.single_interventions.map((e) => [e.id, e.throughput_gain]),
  );
  assert.equal(singles.oven2, 66);
  assert.equal(singles.hours, 0);
  const combos = discoverSynergisticCombos(sess.graph, {});
  assert.ok(combos.length >= 1);
  const top = combos[0];
  assert.equal(top.component_ids.join("+"), "oven2+hours");
  assert.equal(top.synergy_throughput_bonus, 40);
  assert.equal(top.evaluation.throughput_after, 280);

  const opps = generateDynamicOpportunities(sess);
  assert.ok(opps.length >= 2 && opps.length <= 4, `opps=${opps.length}`);
  assert.ok(opps.some((o) => o.kind === "SYNERGISTIC_COMBO"));
  assert.ok(opps.some((o) => o.kind === "KEEP_WHAT_I_HAVE"));
  // After an accept the opportunity space recomputes from the new state:
  // hours is now the unlock (oven2 again would be a third oven, +0 gain).
  const acc = load("bundle_accepted_oven2.json");
  const sess2 = project(acc);
  const opps2 = generateDynamicOpportunities(sess2);
  assert.ok(opps2.some((o) => o.id === "hours"));
  assert.ok(
    !opps2.some(
      (o) => o.id === "oven2" && o.evaluation && o.evaluation.throughput_gain > 0,
    ),
    "third oven must not be offered as a gain",
  );
  // The spent hours path leaves the graph once the shift is accepted.
  const accHours = load("bundle_accepted_oven2_hours.json");
  const sess3 = project(accHours);
  assert.equal(sess3.verificationStatus, "RECEIVER_VERIFIED");
  assert.ok(!sess3.graph.paths.some((p) => p.id === "hours"));
  assert.equal(sess3.graph.constraint_resonance.system_throughput, 280);
  assert.equal(sess3.graph.constraint_resonance.bottleneck_id, "ingredients");
});
